// Package httpapi implements the RESTful API generated by oapi-codegen.
//
// STEP 5 — Every HTTP handler translates the REST request into gRPC call(s),
// and the gRPC reply (or error) back into a REST response:
//
//	client --HTTP/JSON--> Handlers --gRPC--> KVStore server (this node or a peer)
//
// Eight REST operations share three RPCs:
//
//	GET    /v1/keys, /v1/keys/{key}  -> Read   (server stream of entries)
//	POST   /v1/keys, /v1/keys/{key}  -> Update (client stream, op = set)
//	PATCH  /v1/keys, /v1/keys/{key}  -> Update (client stream, op = append|increment)
//	DELETE /v1/keys, /v1/keys/{key}  -> Delete (client stream)
//
// Handlers hold NO application state. That is deliberate: in Parts II-III
// the gRPC target becomes "the server responsible for this request", which
// is exactly the forwarding required by the assignment.
package httpapi

import (
	"context"
	"encoding/json"
	"errors"
	"io"
	"net/http"

	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/status"

	booklibraryv1 "github.com/your-team/kvs/gen/booklibrary/v1"
	"github.com/your-team/kvs/gen/rest"
)

// Handlers implements rest.StrictServerInterface (one method per operationId).
type Handlers struct {
	Library booklibraryv1.BooklibraryClient
}

// ---------------------------------------------------------------------------
//Our own library service methods
// ---------------------------------------------------------------------------

// AddBook implements [rest.StrictServerInterface].
// POST /v1/AllBooks — add a new book to the library.
func (h *Handlers) AddBook(ctx context.Context, request rest.AddBookRequestObject) (rest.AddBookResponseObject, error) {

	out, err := h.Library.AddBook(ctx, &booklibraryv1.AddBookRequest{
		Booktitle: request.Body.Booktitle,
		Author:    request.Body.Author,
		Year:      request.Body.Year,
		Copies:    request.Body.Copies,
	})
	if err != nil {
		return nil, err
	}
	b := bookFromProto(out.GetBook())
	return rest.AddBook201JSONResponse(b), nil
}

// AddCopies implements [rest.StrictServerInterface].
// PATCH /v1/AllBooks/{Booktitle} — add copies to an existing book.
func (h *Handlers) AddCopies(ctx context.Context, request rest.AddCopiesRequestObject) (rest.AddCopiesResponseObject, error) {
	out, err := h.Library.AddCopies(ctx, &booklibraryv1.AddCopiesRequest{
		Booktitle: request.Booktitle,
		Copies:    request.Body.Copies,
	})
	if err != nil {
		return nil, err
	}
	return rest.AddCopies200JSONResponse(bookFromProto(out.GetBook())), nil
}

