// GetAllBooks implements [rest.StrictServerInterface].
// GET /v1/AllBooks
func (h *Handlers) GetAllBooks(ctx context.Context, request rest.GetAllBooksRequestObject) (rest.GetAllBooksResponseObject, error) {
	p := request.Params

	in := &booklibraryv1.GetAllBooksRequest{
		Author:      p.Author,
		Limit:       int32(deref(p.Limit)),
		Consistency: toProtoConsistency(p.Consistency),
	}
	if p.Year != nil {
		year := int64(*p.Year)
		in.Year = &year
	}
	stream, err := h.Library.GetAllBooks(ctx, in)
	if err != nil {
		return nil, err
	}
	books, err := recvBooks(stream)
	if err != nil {
		return nil, err
	}
	return rest.GetAllBooks200JSONResponse{Books: books}, nil
}

// GetBook implements [rest.StrictServerInterface].
// GET /v1/AllBooks/{Booktitle}
func (h *Handlers) GetBook(ctx context.Context, request rest.GetBookRequestObject) (rest.GetBookResponseObject, error) {
	out, err := h.Library.GetBook(ctx, &booklibraryv1.GetBookRequest{
		Booktitle:   request.Booktitle,
		Consistency: toProtoConsistency(request.Params.Consistency),
	})
	if err != nil {
		return nil, err
	}
	return rest.GetBook200JSONResponse(bookFromProto(out.GetBook())), nil
}

// RemoveBook implements [rest.StrictServerInterface].
// DELETE /v1/AllBooks/{Booktitle}
func (h *Handlers) RemoveBook(ctx context.Context, request rest.RemoveBookRequestObject) (rest.RemoveBookResponseObject, error) {
	if _, err := h.Library.RemoveBook(ctx, &booklibraryv1.RemoveBookRequest{
		Booktitle: request.Booktitle}); err != nil {
		return nil, err
	}
	return rest.RemoveBook204Response{}, nil
}

